// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * Semantic validator for Workflow DSL v2 documents.
 *
 * `spec.json` owns standards-based structural validation. These checks add
 * constraints JSON Schema does not express conveniently: cross-step
 * references, unique rule priorities, supported Mongo operators, and
 * non-vacuous guards. The engine runs both validators at its API boundary.
 */
import {
  PLATFORM_USER_ATTRIBUTES,
  STEP_STATES,
  type DiffRule,
  type StepTemplate,
  type UserAttribute,
  type UserAttributeType,
  type WorkflowDSL,
} from './types.ts';

export interface ValidationIssue {
  path: string;
  message: string;
}

const SELECTOR_RULES = new Set(['forAll', 'first', 'firstN', 'group', 'single']);
const STATE_VALUES = new Set<unknown>(STEP_STATES);
/** Operators the engine matcher (engine/src/core/mongo.ts) supports — anything else throws at runtime. */
const MONGO_OPS = new Set([
  '$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin',
  '$exists', '$regex', '$and', '$or', '$not', '$nor',
]);
const SETTABLE = new Set([
  'status',
  'state',
  'completed_at',
  'due_on',
  'assignee',
  'completed_on_delta',
]);

/**
 * Reduce the equivalent spellings of "this field equals X" to X, so the
 * vacuous-guard check is not fooled by `{$eq: X}`, `{$in: [X]}` or a
 * single-clause `$and`. Anything else returns a unique marker.
 */
function literalOf(v: unknown): unknown {
  if (v === null || typeof v !== 'object') return v;
  const o = v as Record<string, unknown>;
  const keys = Object.keys(o);
  if (keys.length === 1) {
    if (keys[0] === '$eq') return literalOf(o.$eq);
    if (keys[0] === '$in' && Array.isArray(o.$in) && o.$in.length === 1) return literalOf(o.$in[0]);
    if (keys[0] === '$and' && Array.isArray(o.$and) && o.$and.length === 1) return literalOf(o.$and[0]);
  }
  return v;
}

/** True when a selector clause already asserts exactly what an `all` clause does. */
function impliesSame(selectorClause: unknown, allClause: unknown): boolean {
  return JSON.stringify(literalOf(selectorClause)) === JSON.stringify(literalOf(allClause));
}

export function validateWorkflow(doc: unknown): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const push = (path: string, message: string) => issues.push({ path, message });

  /**
   * Deep-check a mongo-expr position: every $-prefixed key must be an operator
   * the matcher supports.
   *
   * `objectToken` opts a position into `{"$object": "<path>"}`, and is passed
   * ONLY where the engine substitutes it — the two assignee anchors. Everywhere
   * else the token would survive into `matches()` and throw at request time, so
   * rejecting it here is what keeps that unreachable.
   */
  const LOGICAL = new Set(['$and', '$or', '$nor', '$not']);
  const checkExpr = (path: string, expr: unknown, objectToken = false, valuePos = false): void => {
    if (Array.isArray(expr)) {
      expr.forEach((v, i) => checkExpr(`${path}[${i}]`, v, objectToken, valuePos));
      return;
    }
    if (expr === null || typeof expr !== 'object') return;
    const entries = Object.entries(expr);
    if (objectToken && entries.length === 1 && entries[0][0] === '$object') {
      // A token substitutes to a SCALAR, so it is only meaningful where a value
      // belongs. As a whole branch of $and/$or/$nor/$not — or as the query root
      // — the matcher then gets a scalar where it requires an object and throws
      // `query must be an object`, which is the same "validates clean, 500s at
      // request time" failure the recipients check exists to stop.
      if (!valuePos)
        push(
          `${path}.$object`,
          '$object substitutes to a value, so it cannot stand as a whole query or as a branch of $and/$or/$nor/$not — put it on the right of a field, e.g. {"unit": {"$object": "originating_unit"}}',
        );
      // Sole key with a non-empty string path, or the substituter cannot read it.
      else if (typeof entries[0][1] !== 'string' || entries[0][1] === '')
        push(`${path}.$object`, '$object takes a non-empty object-data path, e.g. {"$object": "originating_unit"}');
      return;
    }
    for (const [key, value] of entries) {
      if (key === '$object')
        push(
          `${path}.$object`,
          objectToken
            ? '$object must be the only key of its object, e.g. {"$object": "division"}'
            : '$object is only substituted in assignee.condition.$or.query and assignee.relative.from_query; elsewhere it reaches the matcher as an unknown operator',
        );
      else if (key.startsWith('$') && !MONGO_OPS.has(key))
        push(`${path}.${key}`, `unsupported query operator "${key}" (engine supports: ${[...MONGO_OPS].join(' ')})`);
      // Descending under a logical operator stays at query level; descending
      // under anything else (a field name, or an operator like $in/$eq) reaches
      // a position where a value belongs.
      checkExpr(`${path}.${key}`, value, objectToken, !LOGICAL.has(key));
    }
  };

  if (typeof doc !== 'object' || doc === null) {
    push('$', 'workflow must be an object');
    return issues;
  }
  const wf = doc as WorkflowDSL;

  if (!wf.init || typeof wf.init !== 'object') {
    push('init', 'missing init block');
    return issues;
  }

  // ── user attributes: what a directory query in this workflow may filter on ──
  const PLATFORM = new Set<string>(PLATFORM_USER_ATTRIBUTES);
  const declared = new Map<string, { type: UserAttributeType; options: Set<string> }>();
  const declaresAttributes = wf.user_attributes !== undefined;
  (Array.isArray(wf.user_attributes) ? wf.user_attributes : []).forEach((attribute, i) => {
    const at = `user_attributes[${i}]`;
    const type = attribute?.type ?? 'choice';
    const isChoice = type === 'choice' || type === 'multi_choice';
    if (!attribute || typeof attribute.key !== 'string')
      push(at, 'a user attribute needs a key');
    else if (isChoice && !(Array.isArray(attribute.options) && attribute.options.length))
      push(`${at}.options`, `a ${type} attribute needs a non-empty options array`);
    else if (!isChoice && attribute.options !== undefined)
      push(`${at}.options`, `a ${type} attribute takes no options`);
    else if (PLATFORM.has(attribute.key))
      push(`${at}.key`, `"${attribute.key}" is a platform attribute (sent with every user) and cannot be redeclared`);
    else if (declared.has(attribute.key)) push(`${at}.key`, `duplicate user attribute "${attribute.key}"`);
    else declared.set(attribute.key, { type, options: new Set(attribute.options ?? []) });
  });
  /** A value a query compares the field against, checked against the field's type. */
  const valueIssue = (path: string, field: string, value: unknown): void => {
    // "" and null are dropped by the directory before matching: not a filter.
    if (value === '' || value === null || value === undefined) return;
    // {"$object": path} compares with the task's own value: no fixed value to check.
    if (typeof value === 'object' && !Array.isArray(value) && Object.keys(value).join() === '$object') return;
    const { type, options } = declared.get(field)!;
    const ok =
      type === 'boolean' ? typeof value === 'boolean'
      : type === 'text' ? typeof value === 'string'
      : typeof value === 'string' && options.has(value);
    if (ok) return;
    push(
      path,
      type === 'choice' || type === 'multi_choice'
        ? `${JSON.stringify(value)} is not an option of user attribute "${field}" (options: ${[...options].join(', ')})`
        : `${JSON.stringify(value)} is not a ${type} for user attribute "${field}"`,
    );
  };
  const RANGE = new Set(['$gt', '$gte', '$lt', '$lte']);
  const checkAttributeValue = (path: string, field: string, value: unknown): void => {
    if (value === null || typeof value !== 'object') return valueIssue(path, field, value);
    if (Array.isArray(value)) return value.forEach((v, i) => checkAttributeValue(`${path}[${i}]`, field, v));
    const { type } = declared.get(field)!;
    for (const [op, operand] of Object.entries(value)) {
      if (op === '$eq' || op === '$ne') valueIssue(`${path}.${op}`, field, operand);
      else if ((op === '$in' || op === '$nin') && Array.isArray(operand))
        operand.forEach((v, i) => valueIssue(`${path}.${op}[${i}]`, field, v));
      else if (op === '$not') checkAttributeValue(`${path}.$not`, field, operand);
      else if (RANGE.has(op))
        push(`${path}.${op}`, `${op} compares an order; user attributes hold no numbers or dates (use options for ranges, e.g. "10-20L")`);
      else if (op === '$regex' && type !== 'text')
        push(`${path}.${op}`, `$regex needs a text attribute; "${field}" is ${type}`);
      // $object and $exists compare against no fixed value
    }
  };
  /**
   * A query run against the directory (assignees, relative anchors, mail
   * recipients). Unchecked unless the workflow declares `user_attributes`: a
   * misspelled field or option matches nobody, and the step is then silently
   * left for manual assignment.
   */
  const checkDirectoryQuery = (path: string, query: unknown): void => {
    if (!declaresAttributes || query === null || typeof query !== 'object') return;
    if (Array.isArray(query)) return query.forEach((q, i) => checkDirectoryQuery(`${path}[${i}]`, q));
    for (const [key, value] of Object.entries(query)) {
      if (LOGICAL.has(key)) checkDirectoryQuery(`${path}.${key}`, value);
      else if (key.startsWith('$') || key === 'ai_context') continue;
      else if (declared.has(key)) checkAttributeValue(`${path}.${key}`, key, value);
      else if (!PLATFORM.has(key.split('.')[0]))
        push(
          `${path}.${key}`,
          `"${key}" is not a user attribute this workflow supports — declare it in user_attributes (declared: ${[...declared.keys()].join(', ') || 'none'}; platform: ${PLATFORM_USER_ATTRIBUTES.join(', ')})`,
        );
    }
  };

  // Spec placeholders ("$mongo_expr", "query", …) are documentation, not queries:
  // the matcher treats a non-object condition as vacuously true, so a workflow
  // registered straight from spec.json would match every task silently.
  const rejectPlaceholder = (path: string, v: unknown) => {
    if (typeof v === 'string')
      push(path, `"${v}" is a spec placeholder, not a query — supply a real mongo expression or omit the field`);
  };
  rejectPlaceholder('init.condition', wf.init.condition);
  rejectPlaceholder('init.apply.default', wf.init.apply?.default);
  if (typeof wf.init.condition === 'object') checkExpr('init.condition', wf.init.condition);
  if (typeof wf.init.apply?.default === 'object') checkExpr('init.apply.default', wf.init.apply.default);

  if (wf.init.transitions !== undefined) {
    const t = wf.init.transitions;
    if (typeof t !== 'object' || t === null || Array.isArray(t)) {
      push('init.transitions', 'transitions must be an object mapping a state to its allowed next states');
    } else {
      for (const [from, tos] of Object.entries(t)) {
        if (!STATE_VALUES.has(from))
          push(`init.transitions.${from}`, `"${from}" is not one of ${STEP_STATES.join('/')}`);
        if (!Array.isArray(tos)) {
          push(`init.transitions.${from}`, 'value must be an array of allowed next states');
          continue;
        }
        tos.forEach((to, i) => {
          if (!STATE_VALUES.has(to))
            push(`init.transitions.${from}[${i}]`, `"${to}" is not one of ${STEP_STATES.join('/')}`);
        });
      }
    }
  }

  /** guard-shaped block: { selector, all, min_matching? } */
  const checkGuardShape = (path: string, g: unknown): void => {
    const guard = g as { selector?: unknown; all?: unknown; min_matching?: unknown };
    if (typeof guard.selector !== 'object' || guard.selector === null)
      push(`${path}.selector`, 'selector must be a mongo query object');
    else checkExpr(`${path}.selector`, guard.selector);
    if (typeof guard.all !== 'object' || guard.all === null)
      push(`${path}.all`, 'all must be a mongo query object');
    else checkExpr(`${path}.all`, guard.all);
    if (guard.min_matching !== undefined && (!Number.isInteger(guard.min_matching) || (guard.min_matching as number) < 1))
      push(`${path}.min_matching`, 'min_matching must be a positive integer');
    // A guard is vacuous only when the selector already implies EVERYTHING
    // `all` asserts — then it passes on the first matching step, silently
    // turning an intended N-of-M into 1-of-M. If `all` adds any constraint the
    // selector does not already make, the guard is meaningful: checking each
    // key in isolation would reject correct guards like
    // selector {status:true} / all {status:true, state:"completed"}.
    if (
      guard.min_matching === undefined &&
      typeof guard.selector === 'object' && guard.selector !== null &&
      typeof guard.all === 'object' && guard.all !== null
    ) {
      const sel = guard.selector as Record<string, unknown>;
      const all = guard.all as Record<string, unknown>;
      const allKeys = Object.keys(all);
      if (allKeys.length > 0 && allKeys.every((k) => k in sel && impliesSame(sel[k], all[k])))
        push(
          `${path}.selector`,
          `selector already requires everything "all" asserts (${allKeys.join(', ')}) — the guard is vacuous and passes on the first match. Widen the selector, or set min_matching for a quorum.`,
        );
    }
  };

  if (wf.init.terminal_when !== undefined) {
    if (typeof wf.init.terminal_when !== 'object' || wf.init.terminal_when === null)
      push('init.terminal_when', 'terminal_when must be { selector, all, min_matching? }');
    else checkGuardShape('init.terminal_when', wf.init.terminal_when);
  }

  const steps: StepTemplate[] = Array.isArray(wf.init.steps) ? wf.init.steps : [];
  if (!Array.isArray(wf.init.steps) || steps.length === 0) {
    push('init.steps', 'init.steps must be a non-empty array');
  }

  const ids = new Set<string>();
  steps.forEach((step, i) => {
    const at = `init.steps[${i}]`;
    if (!step.id) push(`${at}.id`, 'step id is required');
    else if (ids.has(step.id)) push(`${at}.id`, `duplicate step id "${step.id}"`);
    else ids.add(step.id);
    if (!step.title) push(`${at}.title`, 'step title is required');
    if (step.assignee) {
      const { limit, condition } = step.assignee;
      if (limit !== undefined && (!Number.isInteger(limit) || limit < 1))
        push(`${at}.assignee.limit`, 'limit must be a positive integer');
      if (!condition?.$or || (!condition.$or.prompt && !condition.$or.query))
        push(`${at}.assignee.condition`, 'assignee condition needs $or.prompt or $or.query');
      if (step.assignee.require_active !== undefined && typeof step.assignee.require_active !== 'boolean')
        push(`${at}.assignee.require_active`, 'require_active must be a boolean');
      const STRATEGIES = ['first', 'least_loaded', 'round_robin'];
      if (step.assignee.strategy !== undefined && !STRATEGIES.includes(step.assignee.strategy))
        push(`${at}.assignee.strategy`, `strategy must be one of ${STRATEGIES.join('/')}`);
      const rel = step.assignee.relative;
      if (rel !== undefined) {
        if (typeof rel !== 'object' || rel === null) {
          push(`${at}.assignee.relative`, 'relative must be { from_step | from_query, direction?, levels? }');
        } else {
          // Exactly one anchor. Accepting both would leave the engine to pick,
          // and either choice silently ignores half of what the author wrote.
          const anchors = [rel.from_step !== undefined, rel.from_query !== undefined].filter(Boolean).length;
          if (anchors !== 1)
            push(
              `${at}.assignee.relative`,
              anchors === 0
                ? 'relative needs an anchor: from_step (another step\'s holders) or from_query (a directory query)'
                : 'relative takes from_step or from_query, not both',
            );
          if (rel.from_step !== undefined) {
            if (typeof rel.from_step !== 'string')
              push(`${at}.assignee.relative.from_step`, 'from_step must be a step id');
            else if (!ids.has(rel.from_step) && !steps.some((x) => x.id === rel.from_step))
              push(`${at}.assignee.relative.from_step`, `"${rel.from_step}" is not a step id`);
          }
          if (rel.from_query !== undefined) {
            if (typeof rel.from_query !== 'object' || rel.from_query === null || Array.isArray(rel.from_query))
              push(`${at}.assignee.relative.from_query`, 'from_query must be a directory query object');
            else {
              checkExpr(`${at}.assignee.relative.from_query`, rel.from_query, true);
              checkDirectoryQuery(`${at}.assignee.relative.from_query`, rel.from_query);
            }
          }
        }
        if (rel && rel.direction !== undefined && rel.direction !== 'up' && rel.direction !== 'down')
          push(`${at}.assignee.relative.direction`, 'direction must be "up" or "down"');
        if (rel && rel.levels !== undefined && (!Number.isInteger(rel.levels) || rel.levels < 1))
          push(`${at}.assignee.relative.levels`, 'levels must be a positive integer');
      }
      const rr = step.assignee.reresolve_on;
      if (rr !== undefined) {
        if (!Array.isArray(rr) || rr.length === 0)
          push(`${at}.assignee.reresolve_on`, 'reresolve_on must be a non-empty array of states (omit it to keep assignees sticky)');
        else
          rr.forEach((v, j) => {
            if (!STATE_VALUES.has(v))
              push(`${at}.assignee.reresolve_on[${j}]`, `"${v}" is not one of ${STEP_STATES.join('/')}`);
          });
      }
      // `relative` resolves only through reresolveOnEnter. Declared without a
      // reresolve_on it never runs at all, and the step quietly falls back to
      // the plain query — a wrong assignee that looks authored-for.
      if (rel !== undefined && (!Array.isArray(rr) || rr.length === 0))
        push(
          `${at}.assignee.relative`,
          'relative is resolved only when the step is entered, so it is inert without reresolve_on (add e.g. reresolve_on: ["open"])',
        );
      // Its own statement, not an `else` of the block above: chaining it made
      // the query check depend on whether reresolve_on happened to be present.
      if (condition?.$or && typeof condition.$or.query === 'object') {
        checkExpr(`${at}.assignee.condition.$or.query`, condition.$or.query, true);
        checkDirectoryQuery(`${at}.assignee.condition.$or.query`, condition.$or.query);
      }
    }
    if (typeof step.evidence_required?.condition?.$or?.query === 'object')
      checkExpr(`${at}.evidence_required.condition.$or.query`, step.evidence_required.condition.$or.query);
    if (typeof step.comments_required?.condition?.$or?.query === 'object')
      checkExpr(`${at}.comments_required.condition.$or.query`, step.comments_required.condition.$or.query);
    // A misspelled state in required_on matches no transition, silently
    // disabling the demand — exactly the failure this enforcement exists to
    // prevent, so it must not validate.
    for (const spec of ['evidence_required', 'comments_required'] as const) {
      const decl = step[spec];
      if (decl !== undefined && typeof decl.default !== 'boolean')
        push(`${at}.${spec}.default`, 'default is required and must be a boolean — without it the demand is silently off');
      const on = decl?.required_on;
      if (on === undefined) continue;
      if (!Array.isArray(on) || on.length === 0) {
        push(`${at}.${spec}.required_on`, 'required_on must be a non-empty array of states (omit it to demand on every transition)');
        continue;
      }
      on.forEach((v, j) => {
        if (!STATE_VALUES.has(v))
          push(`${at}.${spec}.required_on[${j}]`, `"${v}" is not one of ${STEP_STATES.join('/')}`);
      });
    }
    if (step.completed_at !== undefined) {
      if (step.state?.default !== 'completed')
        push(`${at}.completed_at`, 'completed_at is only for a step that starts completed (state.default "completed")');
      else if (Number.isNaN(Date.parse(String(step.completed_at.default))))
        push(`${at}.completed_at.default`, 'completed_at.default must be a date');
    }
    if (step.due_on && typeof step.due_on.$delta !== 'object')
      push(`${at}.due_on`, 'due_on must be { $delta: { days?, hours?, minutes? } }');
    // Without a due date the extension guard refuses even the FIRST due_on
    // write on the step, so the pairing must hold at registration.
    if (step.due_on_extension !== undefined && step.due_on === undefined)
      push(`${at}.due_on_extension`, 'due_on_extension requires the step to declare due_on — there is nothing to extend otherwise');
    if (step.state !== undefined && !STATE_VALUES.has(step.state.default))
      push(`${at}.state.default`, `state.default must be one of ${STEP_STATES.join('/')}`);
    // With a matrix declared, a state that has no entry has no legal exits, so
    // a step starting there could never move.
    const startState = step.state?.default ?? STEP_STATES[0];
    if (wf.init.transitions && typeof wf.init.transitions === 'object' && !(startState in wf.init.transitions))
      push(
        `${at}.state.default`,
        `step starts in "${startState}", which init.transitions does not declare — it would have no legal transitions`,
      );
  });

  if (wf.init.flatten_order !== undefined) {
    const fo = wf.init.flatten_order;
    if (!Array.isArray(fo)) push('init.flatten_order', 'flatten_order must be an array of step ids');
    else if (fo.length === 0)
      push('init.flatten_order', 'flatten_order must be non-empty (omit it to use declaration order)');
    else {
      const seen = new Set<string>();
      fo.forEach((id, i) => {
        if (typeof id !== 'string' || !ids.has(id))
          push(`init.flatten_order[${i}]`, `"${id}" is not a step id`);
        else if (seen.has(id)) push(`init.flatten_order[${i}]`, `duplicate step id "${id}"`);
        else seen.add(id);
      });
    }
  }

  if (!wf.init.start_id) push('init.start_id', 'start_id is required');
  else if (steps.length && !ids.has(wf.init.start_id))
    push('init.start_id', `start_id "${wf.init.start_id}" is not a step id`);

  const diff: DiffRule[] = Array.isArray(wf.diff) ? wf.diff : [];
  if (!Array.isArray(wf.diff)) push('diff', 'diff must be an array');

  // Rules run in ascending priority; ties resolve by array order, so two rules
  // sharing a priority make the outcome depend on authoring order rather than
  // on anything the author declared.
  const byPriority = new Map<number, number[]>();
  diff.forEach((rule, i) => {
    if (typeof rule?.priority !== 'number') return;
    byPriority.set(rule.priority, [...(byPriority.get(rule.priority) ?? []), i]);
  });
  for (const [priority, idxs] of byPriority)
    if (idxs.length > 1)
      push(
        `diff[${idxs[0]}].priority`,
        `priority ${priority} is shared by rules ${idxs.join(', ')} — ordering would depend on array position; give each rule a distinct priority`,
      );

  diff.forEach((rule, i) => {
    const at = `diff[${i}]`;
    if (typeof rule.priority !== 'number') push(`${at}.priority`, 'priority must be a number');
    if (rule.applicability !== 'all' && rule.applicability !== 'query')
      push(`${at}.applicability`, 'applicability must be "all" or "query"');
    if (rule.applicability === 'query' && !rule.applicability_query)
      push(`${at}.applicability_query`, 'required when applicability is "query"');
    if (!rule.selector || !SELECTOR_RULES.has(rule.selector.rule))
      push(`${at}.selector.rule`, `selector.rule must be one of ${[...SELECTOR_RULES].join('/')}`);
    else {
      if (rule.selector.rule === 'firstN' && !(Number(rule.selector.n) >= 1))
        push(`${at}.selector.n`, 'firstN requires selector.n >= 1');
      if ((rule.selector.rule === 'group' || rule.selector.rule === 'single') && !rule.selector.group_selector)
        push(`${at}.selector.group_selector`, `${rule.selector.rule} requires group_selector`);
    }
    if (typeof rule.applicability_query?.$condn === 'object')
      checkExpr(`${at}.applicability_query.$condn`, rule.applicability_query.$condn);
    if (rule.selector?.group_selector) checkExpr(`${at}.selector.group_selector`, rule.selector.group_selector);
    if (!rule.condition || Object.keys(rule.condition).length === 0)
      push(`${at}.condition`, 'at least one step-property condition is required');
    else {
      for (const [prop, cond] of Object.entries(rule.condition)) {
        const c = cond as Record<string, unknown>;
        if (!('$condn' in c) && !('$delta' in c))
          push(`${at}.condition.${prop}`, 'condition must use $condn or $delta');
        if (typeof c.$condn === 'object') checkExpr(`${at}.condition.${prop}.$condn`, c.$condn);
      }
    }
    if (rule.guard) checkGuardShape(`${at}.guard`, rule.guard);
    if (rule.cohort_guard) {
      const cg = rule.cohort_guard;
      if (!cg.join_on || typeof cg.join_on !== 'string')
        push(`${at}.cohort_guard.join_on`, 'cohort_guard.join_on must be a task property name');
      if (typeof cg.steps !== 'object' || cg.steps === null)
        push(`${at}.cohort_guard.steps`, 'cohort_guard.steps must be a mongo query object');
      if (typeof cg.all !== 'object' || cg.all === null)
        push(`${at}.cohort_guard.all`, 'cohort_guard.all must be a mongo query object');
      for (const k of ['instances', 'steps', 'all'] as const)
        if (typeof cg[k] === 'object' && cg[k] !== null) checkExpr(`${at}.cohort_guard.${k}`, cg[k]);
      // same quorum + vacuous-guard rules as an in-instance guard
      checkGuardShape(`${at}.cohort_guard`, {
        selector: cg.steps,
        all: cg.all,
        min_matching: cg.min_matching,
      });
      for (const [, cond] of Object.entries(rule.condition ?? {}))
        if (cond && typeof cond === 'object' && '$delta' in cond)
          push(`${at}.condition`, 'cohort_guard rules must use $condn conditions ($delta has no changed-step context)');
    }
    const { internal, external } = rule.action ?? {};
    if (!internal && !external) push(`${at}.action`, 'rule needs an internal and/or external action');
    if (internal) {
      if (internal.scope !== 'self' && internal.scope !== 'other')
        push(`${at}.action.internal.scope`, 'scope must be "self" or "other"');
      if (internal.scope === 'other' && !internal.other_selector)
        push(`${at}.action.internal.other_selector`, 'required when scope is "other"');
      else if (internal.other_selector) checkExpr(`${at}.action.internal.other_selector`, internal.other_selector);
      for (const [key, expr] of Object.entries(internal.set ?? {})) {
        if (!SETTABLE.has(key))
          push(`${at}.action.internal.set.${key}`, `"${key}" is not a settable step property`);
        else if (key === 'state' && expr.value !== undefined && expr.value !== '' && !STATE_VALUES.has(expr.value))
          push(`${at}.action.internal.set.state.value`, `state must be one of ${STEP_STATES.join('/')}`);
        if (typeof expr.$condn === 'object') checkExpr(`${at}.action.internal.set.${key}.$condn`, expr.$condn);
      }
    }
    if (external?.email) {
      const r = external.email.recipients;
      if (!r?.$or || (!r.$or.prompt && !r.$or.query))
        push(`${at}.action.external.email.recipients`, 'recipients need $or.prompt or $or.query');
      // Recipients are a directory query like any other, but were never
      // operator-checked: an unsupported operator here validated clean and then
      // threw a 500 out of the matcher when the rule fired, wedging the
      // transition that queued the mail. `$object` is NOT substituted here, so
      // it is rejected with the same message as anywhere else it cannot work.
      else if (typeof r.$or.query === 'object') {
        checkExpr(`${at}.action.external.email.recipients.$or.query`, r.$or.query);
        checkDirectoryQuery(`${at}.action.external.email.recipients.$or.query`, r.$or.query);
      }
    }
    external?.agent?.forEach((a, j) => {
      if (!a.name || !a.prompt)
        push(`${at}.action.external.agent[${j}]`, 'agent needs name and prompt');
    });
  });

  return issues;
}

/** The user attributes a validated workflow declares ([] when it declares none). */
export function declaredUserAttributes(doc: WorkflowDSL): UserAttribute[] {
  return (doc.user_attributes ?? []).map(({ key, type, options }) => ({
    key,
    type: type ?? 'choice',
    ...(options ? { options: [...options] } : {}),
  }));
}

export function assertValidWorkflow(doc: unknown): asserts doc is WorkflowDSL {
  const issues = validateWorkflow(doc);
  if (issues.length) {
    throw new Error(
      `invalid workflow DSL:\n${issues.map((i) => `  - ${i.path}: ${i.message}`).join('\n')}`,
    );
  }
}
